--  DDL for Table EMPLOYEES
--------------------------------------------------------

  CREATE TABLE employees 
   (	employee_id NUMERIC(6,0), 
	first_name VARCHAR(20), 
	last_name VARCHAR(25), 
	email VARCHAR(25), 
	phone_number VARCHAR(20), 
	hire_date DATE, 
	job_id VARCHAR(10), 
	salary NUMERIC(8,2), 
	commission_pct NUMERIC(2,2), 
	manager_id NUMERIC(6,0), 
	department_id NUMERIC(4,0)
   ) ;


--------------------------------------------------------
--  DDL for Index EMP_EMAIL_UK
--------------------------------------------------------

  CREATE UNIQUE INDEX emp_email_uk ON employees (email);
--------------------------------------------------------
--  DDL for Index EMP_EMP_ID_PK
--------------------------------------------------------

  CREATE UNIQUE INDEX emp_emp_id_pk ON employees (employee_id);
--------------------------------------------------------
--  DDL for Index EMP_DEPARTMENT_IX
--------------------------------------------------------

  CREATE INDEX emp_department_ix ON employees (department_id);
--------------------------------------------------------
--  DDL for Index EMP_JOB_IX
--------------------------------------------------------

  CREATE INDEX emp_job_ix ON employees (job_id);
--------------------------------------------------------
--  DDL for Index EMP_MANAGER_IX
--------------------------------------------------------

  CREATE INDEX emp_manager_ix ON employees (manager_id);
--------------------------------------------------------
--  DDL for Index EMP_NAME_IX
--------------------------------------------------------

  CREATE INDEX emp_name_ix ON employees (last_name, first_name);
--------------------------------------------------------
--  Constraints for Table EMPLOYEES
--------------------------------------------------------

  ALTER TABLE employees ADD CONSTRAINT emp_emp_id_pk PRIMARY KEY USING INDEX emp_emp_id_pk;
  ALTER TABLE employees ADD CONSTRAINT emp_email_uk UNIQUE USING INDEX emp_email_uk;
  ALTER TABLE employees ADD CONSTRAINT emp_salary_min CHECK (salary > 0);
  ALTER TABLE employees ALTER COLUMN job_id SET NOT NULL;
  ALTER TABLE employees ALTER COLUMN hire_date SET NOT NULL;
  ALTER TABLE employees ALTER COLUMN email SET NOT NULL;
